def solve():
    n = 5
    max_s = 0
    for e2 in [0, 100]:
        for e3 in [0, 100]:
            for e4 in [0, 100]:
                for e5 in [0, 100]:
                    d = [0] * (n + 1)
                    d[1] = 1
                    d[2] = 1 + e2
                    d[3] = d[1] + d[2] + e3
                    d[4] = d[1] + d[2] + d[3] + e4
                    d[5] = d[1] + d[2] + d[3] + d[4] + e5

                    s = 0
                    for i in range(1, n):
                        s += d[i] / d[i+1]
                    max_s = max(max_s, s)
    print(f"n={n}, max_s={max_s}")

solve()
